# Generated by joobqui-selfhosted sdk:generate from templates/sdks/elixir/test/joobq/config_test.exs.j2. DO NOT EDIT.
defmodule JoobQ.ConfigTest do
  use ExUnit.Case, async: true

  alias JoobQ.Config

  @base [url: "https://joobqui.example.com/", token: "t0ken"]

  test "defaults the options the caller leaves out" do
    config = Config.new!(@base)
    assert config.name == JoobQ
    assert config.url == "https://joobqui.example.com"
    assert config.request_timeout == 60_000
    assert config.pool_size == 50
  end

  test "keeps what the caller gives" do
    config = Config.new!(@base ++ [name: MyApp.JoobQ, request_timeout: 5_000, pool_size: 2])
    assert {config.name, config.request_timeout, config.pool_size} == {MyApp.JoobQ, 5_000, 2}
    assert Config.finch(MyApp.JoobQ) == MyApp.JoobQ.Finch
  end

  test "refuses a missing or wrong option, naming it" do
    assert_raise ArgumentError, ~r/:url/, fn -> Config.new!(token: "t") end
    assert_raise ArgumentError, ~r/:url/, fn -> Config.new!(url: "ftp://x", token: "t") end
    assert_raise ArgumentError, ~r/:token/, fn -> Config.new!(url: "https://x", token: " ") end
    assert_raise ArgumentError, ~r/:pool_size/, fn -> Config.new!(@base ++ [pool_size: 0]) end
    assert_raise ArgumentError, ~r/:queues/, fn -> Config.new!(@base ++ [queues: "mail"]) end

    for name <- [nil, true, false, "JoobQ"] do
      assert_raise ArgumentError, ~r/:name/, fn -> Config.new!(@base ++ [name: name]) end
    end
  end

  test "a producer-only config runs no worker, and the worker options have the contract's defaults" do
    refute Config.worker?(Config.new!(@base))
    config = Config.new!(@base ++ [queues: ["mail"], concurrency: 8])
    assert Config.worker?(config)
    assert {config.prefetch, config.ack_buffer, config.ack_linger} == {4, 32, 5}
    assert {config.lease_ttl_ms, config.drain_timeout} == {30_000, 30_000}
    assert config.worker_id =~ ~r/-JoobQ\z/
    assert Config.new!(@base ++ [queues: ["mail"], concurrency: 1]).prefetch == 1
  end

  test "keeps the worker options the caller gives" do
    opts = [queues: ["a", "b"], worker_id: "w-1", service: "billing", team: "core", prefetch: 0]
    config = Config.new!(@base ++ opts ++ [ack_buffer: 3, ack_linger: 0, lease_ttl_ms: 9_000])
    assert {config.worker_id, config.service, config.team} == {"w-1", "billing", "core"}
    assert {config.prefetch, config.ack_buffer, config.ack_linger} == {0, 3, 0}
    assert config.lease_ttl_ms == 9_000
  end

  test "refuses a wrong worker option, naming it" do
    for {key, value} <- [
          queues: [""],
          queues: [String.duplicate("q", 129)],
          concurrency: 0,
          concurrency: 1001,
          prefetch: -1,
          ack_buffer: 0,
          lease_ttl_ms: 999,
          worker_id: "",
          service: 1,
          drain_timeout: -1
        ] do
      message = ~r/#{inspect(key)}/
      assert_raise ArgumentError, message, fn -> Config.new!(@base ++ [{key, value}]) end
    end
  end

  test "a workflow's task queue is polled, once, beside the queues given" do
    flows = [JoobQ.Workflow.new("a"), JoobQ.Workflow.new("b", task_queue: "mail")]
    config = Config.new!(@base ++ [queues: ["mail"], workflows: flows])
    assert config.queues == ["mail", "workflows"]
    assert config.workflows == flows
    assert Config.worker?(Config.new!(@base ++ [workflows: flows]))
    refute Config.worker?(Config.new!(@base))

    for bad <- [[JoobQ.Workflow.new("a"), JoobQ.Workflow.new("a")], ["s3cr3t"], %{a: 1}] do
      error =
        assert_raise ArgumentError, ~r/:workflows/, fn ->
          Config.new!(@base ++ [workflows: bad])
        end

      refute error.message =~ "s3cr3t"
    end
  end

  test "a workflow whose blueprint cannot be made is refused at start" do
    broken =
      "w"
      |> JoobQ.Workflow.new()
      |> JoobQ.Workflow.update("u", result: JoobQ.Workflow.ref("updates.other"))

    error = assert_raise ArgumentError, fn -> Config.new!(@base ++ [workflows: [broken]]) end
    assert error.message =~ ":workflows" and error.message =~ "update other, not declared"
  end

  test "inspect leaves the token out" do
    config = Config.new!(url: "https://x", token: "s3cr3t-token")
    refute inspect(config) =~ "s3cr3t-token"
    assert inspect(config) =~ "https://x"
  end

  test "an unknown option is named without printing the others (the token)" do
    error =
      assert_raise ArgumentError, fn ->
        Config.new!(url: "https://x", token: "s3cr3t-token", queue: ["default"])
      end

    refute error.message =~ "s3cr3t-token"
    assert error.message =~ ":queue"
    assert_raise ArgumentError, ~r/keyword list/, fn -> Config.new!(["s3cr3t-token"]) end
  end

  test "a repeated option is named without printing the others (the token)" do
    error =
      assert_raise ArgumentError, fn ->
        Config.new!(url: "https://x", token: "s3cr3t-token", url: "https://y")
      end

    refute error.message =~ "s3cr3t-token"
    assert error.message =~ ":url"
  end

  test "options that are not a list raise ArgumentError, not a function clause error" do
    assert_raise ArgumentError, ~r/keyword list/, fn -> Config.new!(%{token: "s3cr3t-token"}) end
  end

  test "a token is trimmed, and one with a space or control character inside is refused" do
    config = Config.new!(url: "https://x", token: "tok-123\n")
    assert Config.token(config) == "tok-123"

    for token <- ["to ken", "tok\nen", "tök"] do
      assert_raise ArgumentError, ~r/:token/, fn ->
        Config.new!(url: "https://x", token: token)
      end
    end
  end

  test "an Erlang crash report (~p) leaves the token out, and the header still gets it" do
    config = Config.new!(url: "https://x", token: "s3cr3t-token")
    refute IO.iodata_to_binary(:io_lib.format(~c"~p", [config])) =~ "s3cr3t-token"
    refute IO.iodata_to_binary(:io_lib.format(~c"~p", [{:start, [config]}])) =~ "s3cr3t-token"
    assert Config.token(config) == "s3cr3t-token"
  end

  test "takes http only for a loopback host or with allow_insecure" do
    for url <- [
          "http://localhost:4000",
          "http://127.0.0.1",
          "http://127.8.9.10/",
          "http://[::1]:4000"
        ] do
      assert %Config{} = Config.new!(url: url, token: "t")
    end

    assert_raise ArgumentError, ~r/:url/, fn ->
      Config.new!(url: "http://joobqui.lan", token: "t")
    end

    assert_raise ArgumentError, ~r/:url/, fn ->
      Config.new!(url: "http://128.0.0.1", token: "t")
    end

    assert Config.new!(url: "http://joobqui.lan/", token: "t", allow_insecure: true).url ==
             "http://joobqui.lan"

    assert_raise ArgumentError, ~r/:allow_insecure/, fn ->
      Config.new!(@base ++ [allow_insecure: "yes"])
    end
  end

  test "refuses a URL with user info, a query or a fragment" do
    for url <- ["https://u:p@x", "https://x/?a=1", "https://x/#top"] do
      assert_raise ArgumentError, ~r/:url/, fn -> Config.new!(url: url, token: "t") end
    end
  end

  test "an error names the option and the value's kind, never the value" do
    for opts <- [
          [url: "https://admin:s3cr3t@x", token: "t"],
          [url: "https://x", token: %{value: "s3cr3t"}],
          [url: "https://x", token: ["s3cr3t"]]
        ] do
      error = assert_raise ArgumentError, fn -> Config.new!(opts) end
      refute error.message =~ "s3cr3t"
    end

    error = assert_raise ArgumentError, fn -> Config.new!(url: "https://x", token: %{}) end

    assert error.message ==
             "JoobQ option :token must be a non-empty string of printable characters, got a map"
  end
end
